@file:Suppress("unused", "MemberVisibilityCanBePrivate")

package tabbit

import java.io.IOException
import java.net.URI
import java.net.http.HttpClient
import java.net.http.HttpRequest
import java.net.http.HttpResponse
import java.nio.charset.StandardCharsets
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.Paths
import java.nio.file.StandardCopyOption
import java.security.MessageDigest
import java.time.Duration
import java.util.Comparator
import kotlin.math.max

/**
 * Tabbit's data updater.
 *
 * Brings a local copy of the exported data up to date with a copy served over HTTP - a
 * CDN, a bucket, a patch server - so a running program can take new data without being
 * redeployed. Emitted beside the reader and reads nothing but the manifest, so it knows
 * nothing about the schema and never has to change when one does.
 *
 * The manifest is what the exporter already writes next to the data: one entry per file
 * with its size and MD5. Comparing it with the local copy is the whole of the diff, so a
 * run downloads what changed and nothing else.
 *
 * Three properties, because a patcher that fails badly is worse than one that does not
 * exist:
 *
 *   Nothing is replaced until everything has arrived and been checked. Files land in a
 *   staging directory first and the local manifest is written last, so an update killed
 *   halfway leaves the previous data readable and the next run redoes the difference.
 *
 *   Every file is checked against the hash the manifest gives for it, so a truncated
 *   transfer that a proxy reported as success does not reach the cache.
 *
 *   A transient failure is retried with a doubling backoff, and a permanent one is not.
 *
 * Reading is somebody else's job. This produces a directory, and the generated tables
 * read it.
 *
 * The Kotlin and Java standard libraries and nothing else: java.net.http for the transfer,
 * MessageDigest for the check, and the small JSON reader at the bottom because neither has
 * one. Its own Kotlin file rather than a call into the Java updater, so a Kotlin project
 * does not have to compile Java to use it.
 */
object TabbitUpdater {
    /** What an update is allowed to do. Every value has a working default. */
    class Options {
        /**
         * The binary exporter writes manifest-binary.json; the JSON exporter writes
         * manifest-json.json.
         */
        var manifestFileName: String = "manifest-binary.json"

        /** The first attempt is included, so three is two retries. */
        var maxAttempts: Int = 3

        /** Waited before the second attempt. Doubled for each attempt after it. */
        var retryDelay: Duration = Duration.ofMillis(500)

        var requestTimeout: Duration = Duration.ofSeconds(30)
        var verifyHash: Boolean = true

        /** Called with one line of progress, when set. */
        var log: ((String) -> Unit)? = null
    }

    /** What an update did. */
    class Result(
        /**
         * The directory holding the data. Hand it to the generated accessor's readAll. Set
         * even on failure, because the previous data is still there and still readable -
         * which is the point of failing the way this does.
         */
        val localPath: Path
    ) {
        var succeeded: Boolean = false
        var error: String? = null
        var upToDate: Boolean = false
        var downloadedCount: Int = 0
        var downloadedBytes: Long = 0
        var deletedCount: Int = 0
    }

    /** One file of the manifest, and the hash to check it by. */
    class ManifestEntry(val name: String, val size: Long, val hash: String)

    /** A failure the same request might survive a moment later. */
    private class TransientException(message: String) : RuntimeException(message)

    /**
     * Brings [cacheDirectory] up to date with the data served under [baseUrl].
     *
     * Does not throw. Everything that can go wrong here - the network, the disk, a file
     * that arrived corrupt - is a condition the caller has to handle rather than a defect,
     * and a patcher that throws into a service's startup is one that gets wrapped in a
     * bare catch that swallows the reason.
     */
    @JvmStatic
    @JvmOverloads
    fun update(baseUrl: String, cacheDirectory: Path, options: Options = Options()): Result {
        val result = Result(cacheDirectory)

        val client = HttpClient.newBuilder()
            .connectTimeout(options.requestTimeout)
            .followRedirects(HttpClient.Redirect.NORMAL)
            .build()

        try {
            val manifestText = String(
                download(client, joinUrl(baseUrl, options.manifestFileName), options),
                StandardCharsets.UTF_8
            )

            val remote = parseManifest(manifestText)
            val local = readLocalManifest(cacheDirectory.resolve(options.manifestFileName))

            val byName = local.associateBy { it.name }

            val wanted = remote.filter { entry ->
                val previous = byName[entry.name]

                // The file's presence is checked as well as the manifest's word for it: a
                // cache somebody cleaned out by hand would otherwise never be refilled.
                previous == null ||
                    previous.hash != entry.hash ||
                    !Files.exists(localPath(cacheDirectory, entry.name))
            }

            val served = remote.map { it.name }.toSet()
            val gone = local.map { it.name }.filter { it !in served }

            if (wanted.isEmpty() && gone.isEmpty()) {
                options.log?.invoke("tabbit: already up to date.")

                result.succeeded = true
                result.upToDate = true
                return result
            }

            options.log?.invoke(
                "tabbit: ${wanted.size} file(s) to fetch, ${gone.size} to remove."
            )

            // Everything lands here first. Nothing the caller can read is touched until the
            // last file has arrived and been checked.
            val staging = cacheDirectory.resolve(".staging")

            Files.createDirectories(cacheDirectory)
            deleteRecursively(staging)
            Files.createDirectories(staging)

            for (entry in wanted) {
                val data = download(client, joinUrl(baseUrl, entry.name), options)

                if (options.verifyHash && entry.hash.isNotEmpty()) {
                    val actual = md5Hex(data)

                    if (!actual.equals(entry.hash, ignoreCase = true)) {
                        throw IllegalStateException(
                            "'${entry.name}' arrived with hash $actual, and the manifest " +
                                "says ${entry.hash}. Nothing was replaced."
                        )
                    }
                }

                val staged = localPath(staging, entry.name)

                Files.createDirectories(staged.parent)
                Files.write(staged, data)

                result.downloadedBytes += data.size
            }

            // From here on the update is applied. Nothing below reaches the network.
            for (name in gone) {
                Files.deleteIfExists(localPath(cacheDirectory, name))
                result.deletedCount += 1
            }

            for (entry in wanted) {
                val target = localPath(cacheDirectory, entry.name)

                Files.createDirectories(target.parent)
                Files.move(
                    localPath(staging, entry.name), target,
                    StandardCopyOption.REPLACE_EXISTING
                )

                result.downloadedCount += 1
            }

            // Last, and that ordering is the recovery story: a run killed before this point
            // leaves a manifest describing the data that is still on disk, so the next run
            // fetches the same files again rather than believing it has them.
            Files.write(
                cacheDirectory.resolve(options.manifestFileName),
                manifestText.toByteArray(StandardCharsets.UTF_8)
            )

            deleteRecursively(staging)

            options.log?.invoke(
                "tabbit: updated. ${result.downloadedCount} fetched, " +
                    "${result.deletedCount} removed."
            )

            result.succeeded = true
            return result
        } catch (error: Exception) {
            // The previous data is untouched, so the caller can carry on with it.
            result.error = error.message ?: error.toString()

            options.log?.invoke("tabbit: update failed: ${result.error}")
            return result
        }
    }

    /** The same, taking the cache directory as a string. */
    @JvmStatic
    @JvmOverloads
    fun update(baseUrl: String, cacheDirectory: String, options: Options = Options()): Result =
        update(baseUrl, Paths.get(cacheDirectory), options)

    /** Reads the entries out of a manifest's JSON. */
    @JvmStatic
    fun parseManifest(text: String): List<ManifestEntry> {
        val manifest = Json.parse(text) as? Map<*, *>
            ?: throw IllegalArgumentException("the manifest is not an object")

        val items = manifest["Items"] as? List<*>
            ?: throw IllegalArgumentException("the manifest has no Items array")

        return items.mapNotNull { item ->
            val fields = item as? Map<*, *> ?: return@mapNotNull null
            val name = fields["Name"] as? String

            if (name.isNullOrEmpty()) {
                null
            } else {
                ManifestEntry(
                    name,
                    (fields["Size"] as? Number)?.toLong() ?: 0L,
                    fields["Hash"] as? String ?: ""
                )
            }
        }
    }

    /** The MD5 of some bytes, in the lower-case hex the manifest carries. */
    @JvmStatic
    fun md5Hex(data: ByteArray): String {
        val digest = MessageDigest.getInstance("MD5").digest(data)
        val hex = StringBuilder(digest.size * 2)

        for (byte in digest) {
            hex.append("0123456789abcdef"[(byte.toInt() shr 4) and 0xF])
            hex.append("0123456789abcdef"[byte.toInt() and 0xF])
        }

        return hex.toString()
    }

    // ------------------------------------------------------------------ transfer

    /** Fetches one URL, retrying what is worth retrying. */
    private fun download(client: HttpClient, url: String, options: Options): ByteArray {
        var delay = max(0L, options.retryDelay.toMillis())
        val attempts = max(1, options.maxAttempts)
        var attempt = 1

        while (true) {
            try {
                return fetch(client, url, options)
            } catch (error: TransientException) {
                if (attempt >= attempts) throw error

                options.log?.invoke(
                    String.format(
                        "tabbit: %s Retrying in %.1fs (%d of %d).",
                        error.message, delay / 1000.0, attempt, attempts
                    )
                )

                Thread.sleep(delay)

                // Doubling rather than a fixed wait: a server refusing because it is
                // overloaded is not helped by every client coming back at the same interval.
                delay *= 2
                attempt += 1
            }
        }
    }

    private fun fetch(client: HttpClient, url: String, options: Options): ByteArray {
        val request = HttpRequest.newBuilder(URI.create(url))
            .timeout(options.requestTimeout)
            .GET()
            .build()

        val response: HttpResponse<ByteArray> = try {
            client.send(request, HttpResponse.BodyHandlers.ofByteArray())
        } catch (error: IOException) {
            // The request never got an answer - DNS, a refused connection, a timeout.
            throw TransientException("'$url' could not be reached: ${error.message}.")
        }

        val status = response.statusCode()

        if (status in 200..299) return response.body()

        val message = "'$url' answered $status."

        // 408 and 429 are the server asking for another attempt, and 5xx is it failing on
        // its own account. A 404 is an answer: retrying it costs three round trips to hear
        // the same thing.
        if (status == 408 || status == 429 || status in 500..599) {
            throw TransientException(message)
        }

        throw IOException(message)
    }

    // --------------------------------------------------------------------- disk

    /**
     * Reads the cached manifest.
     *
     * A missing or unreadable one is an empty manifest, which makes the next update fetch
     * everything - the safe direction to be wrong in.
     */
    private fun readLocalManifest(file: Path): List<ManifestEntry> = try {
        parseManifest(Files.readString(file, StandardCharsets.UTF_8))
    } catch (error: Exception) {
        emptyList()
    }

    /** A manifest name resolved under a directory, with its forward slashes honoured. */
    private fun localPath(directory: Path, name: String): Path {
        var resolved = directory

        for (part in name.split('/')) {
            if (part.isNotEmpty()) resolved = resolved.resolve(part)
        }

        return resolved
    }

    private fun deleteRecursively(directory: Path) {
        if (!Files.exists(directory)) return

        Files.walk(directory).use { paths ->
            paths.sorted(Comparator.reverseOrder()).forEach { Files.deleteIfExists(it) }
        }
    }

    /**
     * Joins a base URL and a file name.
     *
     * Not a path join, which on Windows produces a backslash and a URL no server will
     * answer.
     */
    private fun joinUrl(baseUrl: String, name: String): String =
        baseUrl.trimEnd('/') + "/" + name.replace('\\', '/')

    // --------------------------------------------------------------------- JSON

    /**
     * As much of JSON as reading a manifest needs, which turns out to be all of it.
     *
     * Neither standard library has a JSON reader and the generated output takes no
     * dependencies, so one lives here. Whole rather than special-cased: a parser that
     * understands the grammar is shorter than one that guesses at a shape and has to
     * defend against every way the guess can be wrong.
     *
     * Values come back as Map, List, String, Double, Boolean and null.
     */
    private class Json(private val text: String) {
        private var at = 0

        companion object {
            fun parse(text: String): Any? {
                val reader = Json(text)

                reader.skipWhitespace()
                val value = reader.readValue()
                reader.skipWhitespace()

                require(reader.at == text.length) {
                    "trailing text at offset ${reader.at} in the manifest."
                }

                return value
            }
        }

        private fun readValue(): Any? {
            require(at < text.length) { "the manifest ended early." }

            return when (text[at]) {
                '{' -> readObject()
                '[' -> readArray()
                '"' -> readString()
                't' -> readLiteral("true", true)
                'f' -> readLiteral("false", false)
                'n' -> readLiteral("null", null)
                else -> readNumber()
            }
        }

        private fun readObject(): Map<String, Any?> {
            val fields = LinkedHashMap<String, Any?>()

            at++
            skipWhitespace()

            if (peek() == '}') {
                at++
                return fields
            }

            while (true) {
                skipWhitespace()

                val key = readString()

                skipWhitespace()
                expect(':')
                skipWhitespace()

                fields[key] = readValue()

                skipWhitespace()

                when (val c = next()) {
                    '}' -> return fields
                    ',' -> continue
                    else -> throw IllegalArgumentException(
                        "expected ',' or '}' at offset ${at - 1} in the manifest, not '$c'."
                    )
                }
            }
        }

        private fun readArray(): List<Any?> {
            val values = ArrayList<Any?>()

            at++
            skipWhitespace()

            if (peek() == ']') {
                at++
                return values
            }

            while (true) {
                skipWhitespace()

                values.add(readValue())

                skipWhitespace()

                when (val c = next()) {
                    ']' -> return values
                    ',' -> continue
                    else -> throw IllegalArgumentException(
                        "expected ',' or ']' at offset ${at - 1} in the manifest, not '$c'."
                    )
                }
            }
        }

        private fun readString(): String {
            expect('"')

            val value = StringBuilder()

            while (true) {
                val c = next()

                if (c == '"') return value.toString()

                if (c != '\\') {
                    value.append(c)
                    continue
                }

                when (val escape = next()) {
                    '"' -> value.append('"')
                    '\\' -> value.append('\\')
                    '/' -> value.append('/')
                    'b' -> value.append('\b')
                    'f' -> value.append('')
                    'n' -> value.append('\n')
                    'r' -> value.append('\r')
                    't' -> value.append('\t')
                    'u' -> {
                        require(at + 4 <= text.length) {
                            "a \\u escape ran off the end of the manifest."
                        }

                        value.append(text.substring(at, at + 4).toInt(16).toChar())
                        at += 4
                    }
                    else -> throw IllegalArgumentException(
                        "unknown escape '\\$escape' in the manifest."
                    )
                }
            }
        }

        private fun readNumber(): Double {
            val start = at

            while (at < text.length && text[at] in "+-.eE0123456789") at++

            require(start != at) { "expected a value at offset $at in the manifest." }

            return text.substring(start, at).toDouble()
        }

        private fun readLiteral(literal: String, value: Any?): Any? {
            require(text.startsWith(literal, at)) {
                "expected $literal at offset $at in the manifest."
            }

            at += literal.length
            return value
        }

        private fun skipWhitespace() {
            while (at < text.length && text[at].isWhitespace()) at++
        }

        private fun peek(): Char = if (at < text.length) text[at] else '␀'

        private fun next(): Char {
            require(at < text.length) { "the manifest ended early." }

            return text[at++]
        }

        private fun expect(c: Char) {
            val found = next()

            require(found == c) {
                "expected '$c' at offset ${at - 1} in the manifest, not '$found'."
            }
        }
    }
}
